          <Button
            type="button"
            className="gradient-brand text-white cursor-pointer"
            disabled={update.isPending}
            onClick={() =>
              update.mutate(
                { id: user.id, portalRole: portalRole as "super_admin" | "hr" | "candidate", roleId: roleId || null, status: status as "active" | "invited" | "suspended" },
